import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;
    static long p, k;
    static int tot;
    static long ans;
    static boolean[] vis;
    static int[] val;

    static void modify(long[] x) {
        x[0] = ((x[0] % MOD) + MOD) % MOD;
    }

    static void breadthFirstSearch(int x) {
        tot++;
        int start = x;
        long weight = 1;
        do {
            vis[x] = true;
            x = (int)((x * k) % p);
            weight = (weight * k) % p;
        } while (x != start);
        long[] ansArr = {ans};
        if (weight == 1) {
            ansArr[0] = (ansArr[0] * p) % MOD;
        }
        ans = ansArr[0];
    }

    static void process() {
        if (k == 0) {
            long product = 1;
            for (int i = 1; i <= p - 1; i++) {
                product = (product * p) % MOD;
            }
            System.out.println(product);
            return;
        }
        ans = 1;
        for (int i = 0; i < p; i++) {
            if (!vis[i]) {
                breadthFirstSearch(i);
            }
        }
        System.out.println(ans);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        p = scanner.nextLong();
        k = scanner.nextLong();
        vis = new boolean[(int)p];
        val = new int[(int)p];

        process();

        scanner.close();
    }
}
